//! End to end on the committed iPhone fixture: a Finder backup with a live WAL.
//!
//! The fixture is generated by `tests/fixtures/synthetic/ios/build.py` and committed, so these tests
//! need no ffmpeg, no database of anyone's phone and no network.

use std::path::{Path, PathBuf};

use wexport::ui;

fn fixture() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/synthetic/ios/backup")
}

fn scratch(name: &str) -> PathBuf {
    let path = std::env::temp_dir().join(format!("wexport-ios-{}-{name}", std::process::id()));
    let _ = std::fs::remove_dir_all(&path);
    std::fs::create_dir_all(&path).unwrap();
    path
}

fn build(out: &Path) {
    let args = vec![
        fixture().display().to_string(),
        "-b".into(),
        "all".into(),
        "-t".into(),
        "Europe/Rome".into(),
        "-o".into(),
        out.display().to_string(),
    ];
    assert_eq!(ui::run(&args).expect("build runs"), 0);
}

fn archives(root: &Path) -> Vec<PathBuf> {
    let mut out: Vec<PathBuf> = std::fs::read_dir(root)
        .unwrap()
        .flatten()
        .map(|entry| entry.path())
        .filter(|path| path.is_dir())
        .collect();
    out.sort();
    out
}

#[test]
fn the_backup_is_recognised_and_lists_both_chats() {
    let args = vec![fixture().display().to_string(), "-l".into()];
    assert_eq!(ui::run(&args).expect("list runs"), 0);
}

#[test]
fn the_two_chats_build_archives_that_stand_alone() {
    let out = scratch("self");
    build(&out);
    let names: Vec<String> = archives(&out)
        .iter()
        .map(|path| path.file_name().unwrap().to_string_lossy().to_string())
        .collect();
    assert_eq!(names, ["2026-12-02-family-9fd6", "2026-12-03-alice-8c02"]);
    for archive in archives(&out) {
        for name in [
            "index.html",
            "app.js",
            "app.css",
            "README.txt",
            "data/manifest.js",
        ] {
            assert!(archive.join(name).is_file(), "{name} missing");
        }
    }
    let _ = std::fs::remove_dir_all(&out);
}

#[test]
fn the_message_that_lives_only_in_the_wal_is_in_the_archive() {
    let out = scratch("wal");
    build(&out);
    let alice = out.join("2026-12-03-alice-8c02/data/2026-12.js");
    let chunk = std::fs::read_to_string(&alice).unwrap();
    assert!(
        chunk.contains("last word, only in the log"),
        "the log beside the database is part of it"
    );
    let _ = std::fs::remove_dir_all(&out);
}

#[test]
fn a_file_that_was_not_copied_still_shows_its_stored_thumbnail() {
    let out = scratch("missing");
    build(&out);
    let alice = out.join("2026-12-03-alice-8c02/data/2026-12.js");
    let chunk = std::fs::read_to_string(&alice).unwrap();
    assert!(chunk.contains("\"mi\":1"), "the file is marked as absent");
    assert!(
        chunk.contains("\"th\":\"deriv/"),
        "the phone's preview is still there"
    );
    let _ = std::fs::remove_dir_all(&out);
}

#[test]
fn timestamps_are_rendered_in_the_named_zone() {
    let out = scratch("stamps");
    build(&out);
    let alice = out.join("2026-12-03-alice-8c02/data/2026-12.js");
    let chunk = std::fs::read_to_string(&alice).unwrap();
    assert!(
        chunk.contains("\"s\":\"2026-12-01 10:00:00 +01:00\""),
        "{chunk}"
    );
    let _ = std::fs::remove_dir_all(&out);
}

#[test]
fn the_check_reports_the_missing_file_and_says_the_database_is_sound() {
    let args = vec![fixture().display().to_string(), "-c".into()];
    assert_eq!(
        ui::run(&args).expect("check runs"),
        wexport::error::EXIT_INCOMPLETE
    );
}

#[test]
fn a_dry_run_writes_nothing() {
    let out = scratch("dry");
    let target = out.join("archives");
    let args = vec![
        fixture().display().to_string(),
        "-b".into(),
        "all".into(),
        "-n".into(),
        "-o".into(),
        target.display().to_string(),
    ];
    assert_eq!(ui::run(&args).expect("dry run runs"), 0);
    assert!(!target.exists(), "a dry run writes nothing");
    let _ = std::fs::remove_dir_all(&out);
}

#[test]
fn a_key_is_refused_for_an_iphone_backup() {
    let args = vec![
        fixture().display().to_string(),
        "-k".into(),
        "0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef".into(),
        "-l".into(),
    ];
    let error = ui::run(&args).expect_err("an Android key is not an iPhone key");
    assert!(error.message.contains("iPhone backup is read without one"));
    assert_eq!(error.code, wexport::error::EXIT_INPUT);
}

#[test]
fn an_encrypted_backup_is_refused_as_a_wrong_type() {
    let root = scratch("encrypted");
    let dictionary = {
        let mut dictionary = plist::Dictionary::new();
        dictionary.insert("IsEncrypted".into(), plist::Value::Boolean(true));
        dictionary
    };
    plist::Value::Dictionary(dictionary)
        .to_file_binary(root.join("Manifest.plist"))
        .unwrap();
    std::fs::write(root.join("Manifest.db"), b"not readable").unwrap();
    let error = ui::run(&[root.display().to_string()]).expect_err("an encrypted backup stops here");
    assert_eq!(error.code, wexport::error::EXIT_TYPE);
    assert!(error.message.contains("encrypted with a password"));
    let _ = std::fs::remove_dir_all(&root);
}
